class Solution { public:
 int countGoodNodes(vector<vector<int>>& edges){int n=edges.size()+1;vector<vector<int>>g(n);for(auto&e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}int ans=0;
 function<int(int,int)> dfs=[&](int u,int p){int size=1,ref=-1;bool ok=true;for(int v:g[u])if(v!=p){int x=dfs(v,u);if(ref!=-1&&ref!=x)ok=false;ref=x;size+=x;}if(ok)++ans;return size;};dfs(0,-1);return ans;}
};
